from string import ascii_lowercase

def split_letters(text):
    vowels, consonants = [], []
    for character in text:
        lower = character.lower()
        if lower in 'aeiou':
            vowels.append(character)
        elif lower in ascii_lowercase:
            consonants.append(character)
    return ''.join(vowels), ''.join(consonants)

assert split_letters('Azure 42!') == ('Aue', 'zr')

from math import isqrt

def is_prime(number):
    if isinstance(number, bool) or not isinstance(number, int):
        raise TypeError('number must be an integer, not bool')
    if number < 2:
        return False
    if number == 2:
        return True
    if number % 2 == 0:
        return False
    return all(number % divisor != 0
               for divisor in range(3, isqrt(number) + 1, 2))

assert [is_prime(n) for n in (-3, 0, 1, 2, 17, 49)] == [False, False, False, True, True, False]

def frequencies(values):
    counts = {}
    for value in values:
        counts[value] = counts.get(value, 0) + 1
    return counts

counts = frequencies(['east', 'west', 'east'])
assert counts == {'east': 2, 'west': 1}
keys_to_remove = [key for key, count in counts.items() if count < 2]
for key in keys_to_remove:
    del counts[key]
assert counts == {'east': 2}

def minimum_difference(values):
    ordered = sorted(values)
    if len(ordered) < 2:
        raise ValueError('at least two elements are required')
    return min(right - left for left, right in zip(ordered, ordered[1:]))

assert minimum_difference([8, 2, 3, 11]) == 1
assert minimum_difference([4, 4, 9]) == 0
assert minimum_difference([-8, -3, 6]) == 5

def parse_positive_integer(text):
    if not isinstance(text, str):
        raise TypeError('text must be a string')
    try:
        value = int(text)
    except (ValueError, TypeError) as error:
        raise ValueError('expected an integer string') from error
    if value <= 0:
        raise ValueError('value must be positive')
    return value

assert parse_positive_integer('12') == 12

def unique_chunks(text, width):
    if isinstance(width, bool) or not isinstance(width, int):
        raise TypeError('width must be an integer, not bool')
    if width <= 0:
        raise ValueError('width must be positive')
    return [''.join(dict.fromkeys(text[start:start + width]))
            for start in range(0, len(text), width)]

assert unique_chunks('aabccde', 3) == ['ab', 'cd', 'e']
assert unique_chunks('', 3) == []
